// Some portions generated by Claude
import assert from "node:assert/strict";
import test from "node:test";
import { loadedLinksOf } from "../../../main/frontend/graph-explorer/link-counts.ts";
import { mergeTriples } from "../../../main/frontend/graph-explorer/graph-operations.ts";
import { bindingsToTriples } from "../../../main/frontend/graph-explorer/graph-terms.ts";
import { parseSparqlResponse } from "../../../main/frontend/graph-explorer/rdf-results.ts";
import { EXCLUSION_BUDGET, expandQuery } from "../../../main/frontend/graph-explorer/rdf-vocabulary.ts";

/**
 * A repository that does not certify its blank nodes answers them under a new document identity every time, so the
 * statements Expand already loaded cannot be named in its MINUS. Expand instead leaves out blank neighbours through the
 * predicates whose blank neighbours it already holds; otherwise every Expand would add them again as copies.
 */
const uri = (value) => ({ type: "uri", value });
const blank = (value) => ({ type: "bnode", value });
const row = (source, predicate, target) => ({ source, predicate: uri(predicate), target });

/** The graph as a response without origin negotiation leaves it: every blank node scoped to its document. */
function loaded(rows) {
  const response = parseSparqlResponse(JSON.stringify({ head: { vars: ["source", "predicate", "target"] }, results: { bindings: rows } }));
  return mergeTriples({ nodes: [], edges: [], revision: 0 }, bindingsToTriples(response.results.bindings));
}

const branches = (query) => {
  const parts = query.split(" UNION ");
  return {
    outgoing: parts.filter((part) => part.includes("BIND(?selected AS ?source)")),
    incoming: parts.filter((part) => part.includes("BIND(?selected AS ?target)")),
  };
};

test("document blank neighbours are listed by predicate and direction, once each", () => {
  const graph = loaded([
    row(uri("urn:a"), "urn:p", blank("x")),
    row(uri("urn:a"), "urn:p", blank("y")),
    row(uri("urn:a"), "urn:q", blank("z")),
    row(blank("w"), "urn:r", uri("urn:a")),
    row(uri("urn:a"), "urn:p", uri("urn:b")),
  ]);

  const links = loadedLinksOf(graph, ["urn:a"]).get("urn:a");

  assert.deepEqual(links.blankOutgoing, ["<urn:p>", "<urn:q>"]);
  assert.deepEqual(links.blankIncoming, ["<urn:r>"]);
  assert.deepEqual(links.outgoing, [["<urn:p>", "<urn:b>"]], "named neighbours stay value pairs for the MINUS");
});

test("certified blank nodes are excluded by value, so they add no predicate-wide exclusion", () => {
  const graph = loaded([
    row(uri("urn:a"), "urn:p", { type: "bnode", value: "stored", "rdf4j:reference": true }),
  ]);
  // parseSparqlResponse without repository references scopes every blank node; build the certified one directly.
  const certified = mergeTriples({ nodes: [], edges: [], revision: 0 }, bindingsToTriples([
    row(uri("urn:a"), "urn:p", { type: "bnode", value: "stored", "rdf4j:reference": true }),
  ]));

  const certifiedLinks = loadedLinksOf(certified, ["urn:a"]).get("urn:a");
  assert.deepEqual(certifiedLinks.outgoing, [["<urn:p>", "<_:stored>"]]);
  assert.equal("blankOutgoing" in certifiedLinks, false);
  assert.equal("blankIncoming" in certifiedLinks, false);
  assert.deepEqual(loadedLinksOf(graph, ["urn:a"]).get("urn:a").blankOutgoing, ["<urn:p>"],
    "the same node from an uncertified response is a document blank node");
});

test("legacy unscoped blank IDs from stored workspaces count as document blank nodes", () => {
  const graph = mergeTriples({ nodes: [], edges: [], revision: 0 }, bindingsToTriples([row(uri("urn:a"), "urn:s", blank("legacy"))]));

  assert.deepEqual(loadedLinksOf(graph, ["urn:a"]).get("urn:a").blankOutgoing, ["<urn:s>"]);
});

test("Expand leaves out blank neighbours through loaded predicates, in the matching direction only", () => {
  const graph = loaded([
    row(uri("urn:a"), "urn:p", blank("x")),
    row(uri("urn:a"), "urn:q", blank("z")),
    row(blank("w"), "urn:r", uri("urn:a")),
    row(uri("urn:a"), "urn:p", uri("urn:b")),
  ]);

  const query = expandQuery(["urn:a"], 80, "default", true, loadedLinksOf(graph, ["urn:a"]));
  const { outgoing, incoming } = branches(query);

  assert.equal(outgoing.length, 1);
  assert.equal(incoming.length, 1);
  assert.ok(outgoing[0].includes("FILTER(!isBlank(?target) || ?predicate NOT IN (<urn:p>, <urn:q>))"), outgoing[0]);
  assert.ok(outgoing[0].includes("MINUS { VALUES (?predicate ?target) { (<urn:p> <urn:b>) } }"));
  assert.ok(incoming[0].includes("FILTER(!isBlank(?source) || ?predicate NOT IN (<urn:r>))"), incoming[0]);
  assert.ok(!incoming[0].includes("?target) ||"), "an outgoing exclusion never narrows incoming links");
});

test("Expand without document blank nodes is the query it always was", () => {
  const graph = loaded([row(uri("urn:a"), "urn:p", uri("urn:b"))]);

  const query = expandQuery(["urn:a"], 80, "default", true, loadedLinksOf(graph, ["urn:a"]));

  assert.ok(!query.includes("isBlank"), query);
  assert.equal(expandQuery(["urn:a"], 80, "default", true).includes("isBlank"), false);
});

test("each node of a multi-node Expand gets only its own blank exclusions", () => {
  const graph = loaded([
    row(uri("urn:a"), "urn:p", blank("x")),
    row(uri("urn:b"), "urn:q", blank("y")),
  ]);

  const query = expandQuery(["urn:a", "urn:b"], 12, "default", true, loadedLinksOf(graph, ["urn:a", "urn:b"]));
  const outgoing = branches(query).outgoing;

  const forA = outgoing.find((part) => part.includes("<urn:a>"));
  const forB = outgoing.find((part) => part.includes("<urn:b>"));
  assert.ok(forA.includes("NOT IN (<urn:p>)") && !forA.includes("<urn:q>"), forA);
  assert.ok(forB.includes("NOT IN (<urn:q>)") && !forB.includes("<urn:p>"), forB);
});

test("blank exclusions stay within the Expand budget and skip oversized predicates", () => {
  const long = `<urn:${"x".repeat(600)}>`;
  const many = Array.from({ length: 5000 }, (_, index) => `<urn:predicate:${String(index).padStart(5, "0")}:${"y".repeat(80)}>`);
  const pairs = Array.from({ length: 5000 }, (_, index) => ["<urn:p>", `<urn:target:${index}>`]);
  const links = new Map([["urn:a", { outgoing: pairs, incoming: [], blankOutgoing: [long, ...many] }]]);

  const query = expandQuery(["urn:a"], 80, "default", false, links);
  const outgoing = branches(query).outgoing[0];
  const filter = outgoing.match(/FILTER\(!isBlank\(\?target\)[^\n]*\)\)/)?.[0] ?? "";
  const minus = outgoing.match(/MINUS \{[^\n]*\} \}/)?.[0] ?? "";

  const budget = Math.floor(EXCLUSION_BUDGET / 2);
  assert.ok(filter.length > 0, "a filter is written");
  assert.ok(!filter.includes(long), "a predicate beyond the token limit is not written out");
  assert.ok(filter.includes(many[0]), "the first predicates are kept");
  assert.ok(filter.length + minus.length <= budget + 200, `${filter.length} + ${minus.length} within ${budget}`);
});
